export class ActuatorStore {
 private adapter: ActuatorAdapter
 private state: string = ''
 async execute(command: string): Promise<void> {
  await this.adapter.executeAction(command)
 }
 async synchronize(): Promise<void> {
  const current = await this.adapter.loadCurrent()
  this.state = current
 }
}
